scripts.姚公子对话.txt:
// 与姚公子的同伴对话

	If ($Event == 307) @Event307;
	Return;
	
@Event307:
	Say("独孤剑：如果你以后再敢鱼肉百姓，我可饶不了你！", 9);
	Say("姚公子：不敢，不敢，我再也不敢啦……", 71);
	Return;

scripts.张琳心对话.txt:
// 和张琳心对话

	If ($Event == 300) @Event300;  // 同伴对话
	If ($Event == 304) @Event304;
	If ($Event == 305) @Event304;
	If ($Event == 307) @Event307;
	If ($Event == 360) @Event360;
	
	Return;	
	
@Event300:
	Say("张琳心：酒馆人多，说不定有什么李三的消息。", 21);
	Return;

@Event304:
	Say("张琳心：哥哥，你没事吧？你要去哪里呀？", 24);
	Say("张如梦：我马上就回来……", 20);
	Return;
	
@Event307:
	Say("张琳心：我们快去大牢救李三吧。", 21);
	Return;	

@Event360:
	Say("张琳心：我们快去找那个华山派弟子吧。", 21);
	Say("独孤剑：他下山的时候说去妓院，此刻可能还在那里。", 1);
	Return;

scripts.独孤剑对话.txt:
//和独孤剑说话

	If ($Event == 304) @Event304;
	If ($Event == 305) @Event304;
	Return;
	
@Event304:	
	Say("独孤剑：张兄有何事？不如小弟陪你同去？", 1);
	Say("张如梦：不，不必……", 20);
	Return;

scripts.酒客组3对话.txt:
// 与酒客3的对话

	Say("丁倚天：想我长安几百年帝业，几十朝天子，如今却落到金狗的手里，被洗劫掳掠一空，只怕从此再也不会有昔日的辉煌了。", 0);
	Say("雪梅：公子，何必想那么多？来，喝杯酒，解解愁。", 0);
	Return;

